contract=json.loads((S/'elements.json').read_text('utf8'))
jobs=[]
for e in contract['elements']:
    id=e['id'];x,y,w,h=e['reference_box']
    if id in ['ENV-DEPTH','ENV-UNDERPAINT'] or id.startswith('BUBBLE'):continue
    if id.startswith('BALEEN'):
        edges=[110,275,442,595,742,900,1220];k=int(id[-2:])-1
        shape=f'<rect x="{edges[k]}" y="0" width="{edges[k+1]-edges[k]}" height="340"/>'
    elif id in fish_shapes:
        shape=''.join(f'<ellipse cx="{cx}" cy="{cy}" rx="{rx}" ry="{ry}"/>' for cx,cy,rx,ry in fish_shapes[id])
    elif id.startswith('BEAM'):
        shape=f'<polygon points="{x+50},{y} {x+w},{y} {x+15},{y+h} {x},{y+h-30}"/>'
    elif id in polys:shape=f'<polygon points="{polys[id]}"/>'
    elif id=='LAMP':shape='<ellipse cx="73" cy="402" rx="32" ry="44"/>'
    else:shape=f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="5"/>'
