    (S/'masks'/f'{id}.svg').write_text(svg,encoding='utf8',newline='\n')
    mode='plain'
    if id.startswith(('BALEEN','PLANT','VINE','DECOR')):mode='warm'
    if id.startswith('FISH'):mode='fish'
    if id.startswith('BALEEN'):
        edges=[110,275,442,595,742,900,1220];k=int(id[-2:])-1
        shape=f'<rect x="{edges[k]}" y="0" width="{edges[k+1]-edges[k]}" height="340"/>'
